#include <DHT.h> // biblioteka SWIRC2_DHT.zip z instrukcji
#include <DHT.h>
DHT dht;
const byte cyfry[10] = {63, 6, 91, 79, 102, 109, 125, 7, 127, 111};
int minimum, maksimum, jasnosc = 0, wilgotnosc = 0, temperatura = 0;
int licznik = 0, tryb = 0; // 0 = jasnosc, 1 = wilgotnosc, 2 = temperatura
unsigned long czasDHT = 0;

void cyfra(int n) {
 for (int i = 0; i < 7; i++)
 digitalWrite(i + 2, bitRead(cyfry[n], i) ? LOW : HIGH);
}

void wyswietl(int liczba) {
 liczba = constrain(liczba, 0, 99);
 digitalWrite(10, LOW);
 digitalWrite(11, LOW);
 cyfra(liczba % 10);
 digitalWrite(10, HIGH);
 delay(2);
 digitalWrite(10, LOW);
 cyfra(liczba / 10);
 digitalWrite(11, HIGH);
 delay(2);
 digitalWrite(11, LOW);
}

void setup() {
 for (int i = 2; i <= 8; i++) pinMode(i, OUTPUT);
 pinMode(10, OUTPUT);
 pinMode(11, OUTPUT);
 pinMode(9, INPUT_PULLUP);
 dht.setup(12);
 minimum = maksimum = analogRead(A0);
}

void loop() {
 if (++licznik >= 100) {
 licznik = 0;
 int pomiar = analogRead(A0);
 if (pomiar < minimum) minimum = pomiar;
 if (pomiar > maksimum) maksimum = pomiar;
 if (maksimum > minimum)
 jasnosc = 99L * (pomiar - minimum) / (maksimum - minimum);
 }

 if (millis() - czasDHT >= 2000) {
 czasDHT = millis();
 float h = dht.getHumidity(), t = dht.getTemperature();
 if (!isnan(h)) wilgotnosc = (int)h;
 if (!isnan(t)) temperatura = (int)t;
 }

 if (digitalRead(9) == LOW) {
 delay(25);
 if (digitalRead(9) == LOW) {
 tryb = (tryb + 1) % 3;
 while (digitalRead(9) == LOW) {
 // odswiezaj ekran rowniez, gdy trzymany jest przycisk
 int liczba = tryb == 0 ? jasnosc : (tryb == 1 ? wilgotnosc : temperatura);
 wyswietl(liczba);
 }
 }
 }

 int liczba = tryb == 0 ? jasnosc : (tryb == 1 ? wilgotnosc : temperatura);
 wyswietl(liczba);
}
